e.\n397:  */\n398: export function promptForClosingWorkspaces(promptReason: PromptReason): Promise<boolean> {\n399:   const { openedWindows } = workspace2Store.getState();\n400:   let affectedWorkspaces: OpenedWorkspace[] = [];\n401:   switch (promptReason.reason) {\n402:     case 'CLOSE_WORKSPACE_GROUP': {\n403:       affectedWorkspaces = openedWindows.flatMap((window) => getAffectedWorkspacesInWindow(window));\n404:       break;\n405:     }\n406:     case 'CLOSE_WINDOW': {\n407:       const openedWindow = openedWindows.find((window) => window.windowName === promptReason.windowName);\n408:       if (!openedWindow) {\n409:         throw new Error(`Window ${promptReason.windowName} not found in opened windows.`);\n410:       }\n411:       affectedWorkspaces = getAffectedWorkspacesInWindow(openedWindow);\n412:       break;\n413:     }\n414:     case 'CLOSE_WORKSPACE': {\n415:       const openedWindow = openedWindows.find((window) => window.windowName === promptReason.windowName);\n416:       if (!openedWindow) {\n417:         throw new Error(`Window ${promptReason.windowName} not found in opened windows.`);\n418:       }\n419:       affectedWorkspaces = getAffectedWorkspacesInWindow(openedWindow, promptReason.workspaceName);\n420:       break;\n421:     }\n422:     case 'CLOSE_OTHER_WINDOWS': {\n423:       const windowsToClose = openedWindows.filter((window) => window.windowName !== promptReason.windowNameToSpare);\n424:       affectedWorkspaces = windowsToClose.flatMap((w) => getAffectedWorkspacesInWindow(w));\n425:       break;\n426:     }\n427:   }\n428: \n429:   return showClosePrompt(affectedWorkspaces);\n430: }\n431: \n432: /**\n433:  * Prompts for confirmation to close the workspaces with unsaved changes in the given window: the whole\n434:  * window, or, if `upToWorkspaceName` is given, just that workspace and its children. Unlike\n435:  * `promptForClosingWorkspaces`, this works on any window, including one held in an\n436:  * `<ExportedWorkspace>`'s local st